// Package: Microsoft.SemanticKernel
// Modern SK v1.20+ RAG pipeline using IVectorStore instead of deprecated ISemanticTextMemory.

using Microsoft.SemanticKernel;
using Microsoft.SemanticKernel.VectorStores;
using Microsoft.Extensions.AI;

public sealed class SemanticKernelRagPipeline
{
    private readonly Kernel _kernel;
    private readonly IVectorStore _vectorStore;
    private readonly IEmbeddingGenerator<string, Embedding<float>> _embeddingGenerator;
    private const string CollectionName = "rag-documents";

    public SemanticKernelRagPipeline(
        Kernel kernel,
        IVectorStore vectorStore,
        IEmbeddingGenerator<string, Embedding<float>> embeddingGenerator)
    {
        _kernel = kernel ?? throw new ArgumentNullException(nameof(kernel));
        _vectorStore = vectorStore ?? throw new ArgumentNullException(nameof(vectorStore));
        _embeddingGenerator = embeddingGenerator ?? throw new ArgumentNullException(nameof(embeddingGenerator));
    }

    public async Task IngestAsync(
        IEnumerable<string> documents,
        CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(documents);

        var chunkIndex = 0;

        foreach (var document in documents)
        {
            // Simple chunking by sentences; replace with a dedicated chunker for production
            var chunks = document.Split(new[] { ". " }, StringSplitOptions.RemoveEmptyEntries);

            foreach (var chunk in chunks)
            {
                var embedding = await _embeddingGenerator.GenerateAsync(chunk, ct);

                var record = new VectorStoreRecord
                {
                    Id = $"chunk-{chunkIndex}",
                    Text = chunk,
                    Vector = embedding.Vector.ToArray()
                };

                await _vectorStore.UpsertAsync(CollectionName, record, ct);
                chunkIndex++;
            }
        }
    }

    public async Task<string> AskAsync(string question, CancellationToken ct = default)
    {
        ArgumentNullException.ThrowIfNull(question);

        var queryEmbedding = await _embeddingGenerator.GenerateAsync(question, ct);

        var results = await _vectorStore.SearchAsync<VectorStoreRecord>(
            CollectionName,
            queryEmbedding.Vector,
            new VectorSearchOptions { Top = 5 },
            ct);

        var context = string.Join(
            "\n---\n",
            results.Select(r => r.Text));

        var prompt = $"""
Context:
{context}

Question:
{question}

Answer using only the context above. If the answer is not in the context, say so.
""";

        var arguments = new KernelArguments();
        arguments["input"] = prompt;

        var result = await _kernel.InvokePromptAsync<string>(prompt, arguments, ct);

        return result;
    }
}

public sealed class VectorStoreRecord : IVectorStoreRecord<string>
{
    public string Id { get; set; } = string.Empty;
    public string Text { get; set; } = string.Empty;
    public ReadOnlyMemory<float> Vector { get; set; }
}

